"""Seeds (design section 8.1): generated by the template's seed
generator or read from files, each with a declaration block, evaluated
on the full graph before iteration 1. The first seed's values are what
`seed.<node>.<output>` refers to."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Optional

from . import artifacts as A
from .declaration import parse_block, render_block
from .errors import BindError
from .evaluate import (Candidate, candidate_from_program, declaration_program,
                       evaluate_candidate, program_from_seed_text)
from .expr import to_json
from .instance import Instance
from .nodes import Executor
from .registry import PRIORS


def seed_programs(instance: Instance, run: Optional[Path] = None) -> list:
    """[(name, program text)] for every seed of `search.seeds`: the
    generated names, the files, and the plans the discover role
    proposed (`<run>/discovered.json`, through the template's
    `plan_seed`)."""
    s = instance.search.get("seeds") or {}
    out = []
    ctx = instance.ctx()
    tpl = instance.template
    seeds = instance.seed_artifacts()
    for name in s.get("generated") or []:
        res = tpl.seed_generator(ctx, name)
        if instance.is_numeric:
            vars_, lines = _decl_parts(res, name)
            out.append((name, declaration_program(instance, vars_, lines)))
            continue
        a = seeds[0]
        texts, vars_, lines = _seed_texts(a, res, name)
        out.append((name, program_from_seed_text(instance, texts, vars_, lines)))
    for i, f in enumerate(s.get("files") or []):
        p = A.resolve_file(str(f), instance.base_dir)
        text = p.read_text()
        name = p.stem
        if instance.is_numeric:
            d = parse_block(text)
            if not d.present:
                raise BindError("search.seeds.files", f"{f}: no declaration block")
            out.append((name, declaration_program(instance, d.vars, d.lines)))
            continue
        a = seeds[0]
        if a.is_family:
            raise BindError("search.seeds.files", "a file seed for a family needs one file per "
                                                  "member; use the seed generator")
        d = parse_block(text)
        if not d.present:
            if instance.searched():
                raise BindError("search.seeds.files", f"{f}: no declaration block, and the "
                                                      f"instance has searched variables")
            out.append((name, program_from_seed_text(instance, {"": text}, {}, [])))
        else:
            out.append((name, A.assemble_program(a, {"": text}, None, tpl.comment_syntax)))
    # the discovered plans come after the listed seeds: the first seed is the score reference
    from .discover import discovered_plans
    # `seeds.discovered: false`: the run starts from its listed seeds alone, whatever discovered.json the run
    # directory holds (an ablation without the numeric front, a control over a plain program)
    use = (s.get("discovered", True) is not False) and run
    for name, plan in (discovered_plans(run) if use else {}).items():
        try:
            res = tpl.plan_seed(ctx, name, plan)
        except Exception as e:  # noqa: BLE001
            raise BindError("search.seeds.discover", f"plan {name!r} in discovered.json: {e}") from None
        if instance.is_numeric:
            vars_, lines = _decl_parts(res, name)
            out.append((name, declaration_program(instance, vars_, lines)))
            continue
        texts, vars_, lines = _seed_texts(seeds[0], res, name)
        out.append((name, program_from_seed_text(instance, texts, vars_, lines)))
    if not out and not instance.is_numeric:
        a = seeds[0]
        d = parse_block(a.text)
        if not d.present and instance.searched():
            raise BindError("search.seeds", "no seeds listed, and the seed artifact has no "
                                            "declaration block for the searched variables")
        out.append(("artifact", program_from_seed_text(instance, dict(a.texts), d.vars, d.lines)
                    if not d.present else A.assemble_program(a, dict(a.texts), None, tpl.comment_syntax)))
    if not out:
        raise BindError("search.seeds", "a numeric backend needs at least one seed declaration")
    names = [n for n, _ in out]
    if len(set(names)) != len(names):
        raise BindError("search.seeds", f"duplicate seed names {names}")
    return out


def _decl_parts(res, name):
    if isinstance(res, tuple) and len(res) == 3:
        _, vars_, lines = res
        return dict(vars_), list(lines)
    if isinstance(res, dict):
        return dict(res), []
    if isinstance(res, str):
        d = parse_block(res)
        return d.vars, d.lines
    raise BindError("search.seeds.generated", f"{name}: the seed generator returned {type(res).__name__}")


def _seed_texts(a: A.Artifact, res, name):
    """(member texts, decl vars, decl lines) from a seed generator's
    return value: a text, {member: text}, or (text | {member: text},
    vars, lines)."""
    vars_, lines = {}, []
    if isinstance(res, tuple) and len(res) == 3:
        res, vars_, lines = res
    if isinstance(res, str):
        if a.is_family:
            raise BindError("search.seeds.generated", f"{name}: a family needs {{member: text}}")
        texts = {"": res}
    elif isinstance(res, dict):
        if not a.is_family:
            raise BindError("search.seeds.generated", f"{name}: a text, not members")
        missing = [m for m in a.members if m not in res]
        if missing:
            raise BindError("search.seeds.generated", f"{name}: no text for members {missing}")
        texts = {m: str(res[m]) for m in a.members}
    else:
        raise BindError("search.seeds.generated", f"{name}: the seed generator returned "
                                                  f"{type(res).__name__}")
    return texts, dict(vars_), list(lines)


def completed_seeds(run: Path) -> list:
    """[(name, program path, record path)] for every seed directory that
    holds both a program and its record.

    `run_seeds` writes the program, evaluates it, and writes the record
    last, so a seeds run that was interrupted leaves directories carrying a
    program and no record. Those are not seeds a search can start from, and
    the test for `adir run` has to be this rather than the presence of the
    directory: `seeds/` exists from the moment the first one is written."""
    out = []
    for d in sorted(Path(run).glob("seeds/*/")):
        rec = d / "record.json"
        progs = sorted(d.glob("program.*"))
        if rec.is_file() and progs:
            out.append((d.name, progs[0], rec))
    return out


def run_seeds(instance: Instance, run: Path, executor: Optional[Executor] = None,
              log=None) -> list:
    """Generate, write and evaluate the seeds; write seed_values.json
    from the first."""
    run = Path(run)
    (run / "seeds").mkdir(parents=True, exist_ok=True)
    archive = instance.archive(run)
    executor = executor or Executor(run / "cache")
    programs = seed_programs(instance, run)
    rank = (instance.search.get("seeds") or {}).get("rank")
    if rank and rank.get("prior"):
        programs = _rank(instance, programs, rank)
    ext = _ext(instance)
    records, seed_values, done = [], {}, []
    for i, (name, program) in enumerate(programs):
        d = run / "seeds" / name
        d.mkdir(parents=True, exist_ok=True)
        (d / f"program{ext}").write_text(program)
        cand = candidate_from_program(instance, program, is_seed=True, seed_name=name,
                                      meta={"candidate_id": f"seed:{name}",
                                            "source_path": str(d / f"program{ext}")})
        rec = evaluate_candidate(instance, run, cand, seed_values=seed_values, archive=archive,
                                 executor=executor, seed_programs=done, log=log)
        (d / "record.json").write_text(json.dumps(rec, indent=1, default=str))
        from .composer import save_program
        save_program(run, rec["candidate_id"], ext, program)
        records.append(rec)
        done.append(program)
        if i == 0:
            seed_values = {n: m["value"] for n, m in rec["measurements"].items()}
            seed_values["__goal__"] = rec["goal_values"]
            (run / "seeds" / "seed_values.json").write_text(json.dumps(seed_values, default=str))
    return records


def _resolved_vars(instance: Instance, d) -> dict:
    """The block's completed declaration: every decision it states plus
    every decision it leaves out, at that decision's default. The block
    carries departures alone, so a prior that prices a structure by its
    family sees nothing for a structure standing at its default without
    this."""
    from .declaration import check_declaration
    try:
        ctx = instance.ctx(declaration=d)
        outs = check_declaration(instance, d, ctx)
    except Exception:  # noqa: BLE001 - a block the checker rejects is priced from its VAR lines
        return dict(d.vars)
    got = {k[len("decl."):]: v for k, v in outs.items() if k.startswith("decl.")}
    got.update(d.vars)                     # a VAR line wins over the resolved value
    return got


def _rank(instance: Instance, programs: list, rank: dict) -> list:
    prior = PRIORS[rank["prior"]]
    scored = []
    for name, program in programs:
        d = parse_block(program)
        lines: dict = {}
        for kind_, tokens in d.lines:
            lines.setdefault(kind_, []).append(tokens)
        try:
            # the completed declaration by variable name, and every domain line of a kind under
            # that kind's name: a prior that prices a declaration reads each STRUCTURE line, so
            # the lines are grouped rather than collapsed to the last one of each kind
            value, lo, hi = prior.predict(_resolved_vars(instance, d) | lines)
        except Exception:  # noqa: BLE001
            value = float("inf")
        scored.append((value, name, program))
    d0 = instance.goal.levels[0][0]
    scored.sort(key=lambda t: t[0] if d0 == "minimize" else -t[0])
    top = int(rank.get("top") or len(scored))
    return [(n, p) for _, n, p in scored[:top]]


def _ext(instance: Instance) -> str:
    seeds = instance.seed_artifacts()
    if not seeds:
        return ".txt"
    lang = seeds[0].language
    return {"c": ".c", "cpp": ".cc", "systemverilog": ".sv", "verilog": ".v", "python": ".py",
            "chisel": ".scala", "scala": ".scala", "yosys_script": ".ys", "tcl": ".tcl",
            "rust": ".rs", "go": ".go"}.get(lang, ".txt")
